add_action( 'wp_footer', 'perfectpixel_prevent_copy' );

function perfectpixel_prevent_copy() {
	if ( current_user_can( 'edit_posts' ) ) {
		return;
	}
	?>
	<style>body{-webkit-user-select:none;user-select:none}input,textarea,select,[contenteditable="true"]{-webkit-user-select:text;user-select:text}</style>
	<script>
	( function () {
		var editable = function ( el ) {
			return el && el.closest && el.closest( 'input, textarea, select, [contenteditable="true"]' );
		};
		[ 'contextmenu', 'copy', 'cut' ].forEach( function ( type ) {
			document.addEventListener( type, function ( event ) {
				if ( ! editable( event.target ) ) {
					event.preventDefault();
				}
			} );
		} );
		document.addEventListener( 'dragstart', function ( event ) {
			if ( event.target && 'IMG' === event.target.tagName ) {
				event.preventDefault();
			}
		} );
	} )();
	</script>
	<?php
}
